// VraFormLibraryPlan The form library entry a vRO action becomes (ADR-0043), when a
// custom form takes its choices or a field's default from it and its
// script makes one GET to a URL the import can read: a REST value
// source, the action's inputs the URL reads its parameters. The
// fields that use the action name the entry at `version`.
type VraFormLibraryPlan struct {
	// Action What the import does: make the entry; nothing, as rvav's is
	// what the action gives; nothing, as rvav has another entry of
	// that key (the import never changes one); nothing, as the action
	// can't be one (`notes` say why: its fields keep a note naming
	// it).
	Action VraFormLibraryPlanAction `json:"action"`
	Key    string                   `json:"key"`
	Name   string                   `json:"name"`
	Notes  []VraNote                `json:"notes"`

	// Parameters The action's inputs the URL reads, the entry's parameters.
	Parameters []string `json:"parameters"`

	// Url The entry's URL, its parameters as ${params.x}.
	Url *string `json:"url,omitempty"`

	// Version The version the items name: the one the import makes, or rvav's latest; 0 when skipped.
	Version int `json:"version"`

	// VroAction The action as forms name it: module/name.
	VroAction string `json:"vro_action"`
}

